/* a11y-injection-kit bundle
 *
 * Generated by tools/bundle.mjs. Do not edit this file: edit the sources
 * listed below and run `npm run bundle`. CI fails if the two disagree.
 *
 * Paste into the platform code injection box, footer or body end, and read
 * the README first. Everything the platform editor can set should be set in
 * the editor. What is left is what this is for.
 *
 *   lib/text.js
 *   lib/accessible-name.js
 *   shared/a11y-injection-kit.js
 *   rules/01-skip-link.js
 *   rules/02-name-controls.js
 *   rules/03-filename-alt.js
 *   rules/04-name-iframes.js
 *   rules/05-mobile-nav-focus.js
 *   rules/06-summary-read-more.js
 *   rules/07-gallery-controls.js
 *   rules/08-announcement-close.js
 */

/* ===== lib/text.js ===== */
/* ---------------------------------------------------------------------------
   lib/text.js

   String judgements shared by the repair rules and the audits. Nothing in
   here touches the DOM, which is deliberate: these are the decisions that
   were previously written inline, slightly differently, in each rule, and
   they are the decisions most likely to be wrong in an interesting way.

   Exposed as window.A11yText so it works when pasted into a code injection
   box, and loadable in Node for unit tests without a browser.
   --------------------------------------------------------------------------- */

(function (global) {
  'use strict';

  var IMAGE_EXTENSIONS = /\.(jpe?g|png|gif|webp|svg|avif|bmp|tiff?)$/i;

  /* Collapse runs of whitespace, including the non-breaking space that
     platform editors insert when an author presses space twice. An element
     whose only content is a non-breaking space is not named. */
  function normalize(value) {
    if (value === null || value === undefined) return '';
    return String(value).replace(/[\s ]+/g, ' ').trim();
  }

  /* True when an alt value is a filename carrying no information.

     The test is deliberately narrow. "Our 2024 team at the summer picnic"
     is prose and must survive; "DSC_0043.JPG" and "hero-image-final-2.png"
     are filenames and do not. The distinguishing feature is not the
     extension on its own, because "Figure 1. The site map." also ends in a
     dot, but an extension preceded by a token with no spaces. */
  function isFilenameAlt(alt) {
    var value = normalize(alt);
    if (!value) return false;
    if (!IMAGE_EXTENSIONS.test(value)) return false;
    if (/\s/.test(value)) return false;
    return /^[\w.-]+$/.test(value);
  }

  /* Link text that is identical on every item in a list, which is the
     summary block and blog grid failure. Matched against the normalized
     visible text, case insensitively. */
  var GENERIC_LINK_TEXT = [
    'read more', 'readmore', 'more', 'learn more', 'continue reading',
    'continue', 'details', 'view', 'view more', 'see more', 'click here',
    'here', 'this', 'link', 'go', 'open'
  ];

  function isGenericLinkText(text) {
    var value = normalize(text).toLowerCase().replace(/[.!…>\s]+$/, '');
    return GENERIC_LINK_TEXT.indexOf(value) !== -1;
  }

  /* Map a probe string, assembled from an element's test ids and class
     names, to a name we are confident enough to apply.

     Ordered most specific first. "close" is tested before "search" because
     a control named something like "search-close" is a close button. There
     is no fallback on purpose: a control we cannot identify is reported for
     a human to name in the editor, never guessed at. */
  var HINTS = [
    [/\bclose\b|\bdismiss\b|\bcancel\b/i, 'Close'],
    [/\bmenu\b|\bhamburger\b|\bburger\b|\bnav-toggle\b/i, 'Open menu'],
    [/\bsearch\b|\bmagnif/i, 'Search'],
    [/\bprev(ious)?\b|\bback\b|left-arrow|arrow-left/i, 'Previous'],
    [/\bnext\b|\bforward\b|right-arrow|arrow-right/i, 'Next'],
    [/\bplay\b/i, 'Play'],
    [/\bpause\b/i, 'Pause'],
    [/\bmute\b/i, 'Mute'],
    [/\bcart\b|\bbasket\b|\bbag\b/i, 'Cart'],
    [/\baccount\b|\bprofile\b|\blogin\b/i, 'Account']
  ];

  function hintFor(probe) {
    var value = normalize(probe);
    if (!value) return null;
    for (var i = 0; i < HINTS.length; i++) {
      if (HINTS[i][0].test(value)) return HINTS[i][1];
    }
    return null;
  }

  /* A CSS identifier generated by a closed platform, such as Wix's _1a2b3c
     or a hashed module class. Selectors built on these break on the next
     publish, so the rules refuse to use them and the verifier refuses to
     ship them. */
  function isGeneratedClassName(name) {
    var value = normalize(name);
    if (!value) return false;
    if (/^_[A-Za-z0-9]{4,}$/.test(value)) return true;
    if (/^[A-Za-z][\w-]*__[A-Za-z0-9]{5,}$/.test(value)) return true;
    return /^[A-Za-z][\w-]*-[a-f0-9]{6,}$/.test(value);
  }

  global.A11yText = {
    normalize: normalize,
    isFilenameAlt: isFilenameAlt,
    isGenericLinkText: isGenericLinkText,
    hintFor: hintFor,
    isGeneratedClassName: isGeneratedClassName,
    GENERIC_LINK_TEXT: GENERIC_LINK_TEXT
  };
})(typeof window !== 'undefined' ? window : this);

/* ===== lib/accessible-name.js ===== */
/* ---------------------------------------------------------------------------
   lib/accessible-name.js

   One accessible name computation, used by every rule and every audit.

   This file exists because of a defect rather than a principle. Five of the
   repair rules in this repository previously decided "is this control already
   named?" with their own inline expression, and all five agreed on the same
   wrong answer: they read textContent. A button whose only content is an
   image with correct alt text has an empty textContent and a perfectly good
   accessible name, so every one of those rules treated it as unnamed and
   appended a second name to it. The result on a real site is a control that
   announces "Close Close", produced by the layer that was installed to fix
   naming.

   Scope. This implements the part of accname that a repair layer on a closed
   platform actually needs, and nothing else:

     aria-labelledby, then aria-label, then the native host-language label,
     then title.

   What it does not implement is listed in docs/03-what-the-kit-cannot-reach.md
   and the short version is: no CSS generated content, no aria-describedby, no
   recursive traversal through further labelledby references, and no attempt
   to resolve a name through a cross-origin iframe. A repair layer that needs
   those is a repair layer that has been pushed past its honest limit.

   Exposed as window.A11yName.
   --------------------------------------------------------------------------- */

(function (global) {
  'use strict';

  var T = global.A11yText;

  /* Form controls take their name from a label, never from their contents.
     A select is named by its label, not by whichever option happens to be
     selected, and getting that wrong makes every unlabelled select on a site
     look labelled. */
  var NAME_FROM_LABEL = ['INPUT', 'SELECT', 'TEXTAREA', 'PROGRESS', 'METER'];

  /* Elements that contribute nothing to the name of an ancestor. */
  var NOT_RENDERED = ['SCRIPT', 'STYLE', 'TEMPLATE', 'NOSCRIPT', 'HEAD'];

  function isHidden(el) {
    if (!el || el.nodeType !== 1) return false;
    if (el.hasAttribute('hidden')) return true;
    if (el.getAttribute('aria-hidden') === 'true') return true;
    var doc = el.ownerDocument;
    var view = doc && doc.defaultView;
    if (!view || !view.getComputedStyle) return false;
    var style = view.getComputedStyle(el);
    return style.display === 'none' || style.visibility === 'hidden';
  }

  /* The text an element contributes when it is part of an ancestor's name.
     Images contribute their alt. This single line is the defect described at
     the top of the file. */
  function contributedText(node) {
    if (!node) return '';
    if (node.nodeType === 3) return node.nodeValue || '';
    if (node.nodeType !== 1) return '';
    if (NOT_RENDERED.indexOf(node.tagName) !== -1) return '';
    if (isHidden(node)) return '';

    var label = node.getAttribute('aria-label');
    if (T.normalize(label)) return ' ' + T.normalize(label) + ' ';

    if (node.tagName === 'IMG' || node.tagName === 'AREA') {
      return ' ' + T.normalize(node.getAttribute('alt')) + ' ';
    }
    if (node.tagName === 'SVG' || node.tagName === 'svg') {
      var titleEl = node.querySelector && node.querySelector('title');
      return titleEl ? ' ' + T.normalize(titleEl.textContent) + ' ' : '';
    }
    if (node.tagName === 'INPUT') {
      var type = (node.getAttribute('type') || '').toLowerCase();
      if (type === 'submit' || type === 'reset' || type === 'button') {
        return ' ' + T.normalize(node.value || node.getAttribute('value')) + ' ';
      }
      if (type === 'image') {
        return ' ' + T.normalize(node.getAttribute('alt')) + ' ';
      }
      return '';
    }
    if (NAME_FROM_LABEL.indexOf(node.tagName) !== -1) return '';

    var out = '';
    for (var i = 0; i < node.childNodes.length; i++) {
      out += contributedText(node.childNodes[i]);
    }
    return out;
  }

  function fromLabelledBy(el) {
    var ids = T.normalize(el.getAttribute('aria-labelledby'));
    if (!ids) return '';
    var doc = el.ownerDocument;
    var parts = [];
    ids.split(' ').forEach(function (id) {
      var target = doc.getElementById(id);
      if (!target) return;
      /* A referenced element contributes its own aria-label if it has one,
         and otherwise its text. It does not recurse into a further
         labelledby, which is where accname stops too. */
      var own = T.normalize(target.getAttribute('aria-label'));
      parts.push(own || T.normalize(contributedText(target)));
    });
    return T.normalize(parts.join(' '));
  }

  /* The native label of a form control: a wrapping label element, or one
     pointing at it with for. */
  function fromNativeLabel(el) {
    var doc = el.ownerDocument;
    var parts = [];
    if (el.id) {
      var forLabels = doc.querySelectorAll('label[for="' + CSS.escape(el.id) + '"]');
      for (var i = 0; i < forLabels.length; i++) {
        parts.push(T.normalize(contributedText(forLabels[i])));
      }
    }
    var wrapping = el.closest && el.closest('label');
    if (wrapping && parts.length === 0) {
      parts.push(T.normalize(contributedText(wrapping)));
    }
    return T.normalize(parts.join(' '));
  }

  /* The accessible name of an element, or the empty string when it has
     none. Never returns null, so callers cannot accidentally treat a missing
     name as a present one. */
  function accessibleName(el) {
    if (!el || el.nodeType !== 1) return '';

    var byRef = fromLabelledBy(el);
    if (byRef) return byRef;

    var label = T.normalize(el.getAttribute('aria-label'));
    if (label) return label;

    if (el.tagName === 'IMG' || el.tagName === 'AREA') {
      var alt = el.getAttribute('alt');
      /* alt="" is a deliberate statement that the image is decorative, and
         is a valid name of none. alt missing entirely is a defect. */
      if (alt !== null) return T.normalize(alt);
    }

    if (el.tagName === 'IFRAME' || el.tagName === 'FRAME') {
      return T.normalize(el.getAttribute('title'));
    }

    if (NAME_FROM_LABEL.indexOf(el.tagName) !== -1) {
      var native = fromNativeLabel(el);
      if (native) return native;
      var type = (el.getAttribute('type') || '').toLowerCase();
      if (el.tagName === 'INPUT' && (type === 'submit' || type === 'reset' || type === 'button')) {
        var v = T.normalize(el.value || el.getAttribute('value'));
        if (v) return v;
      }
      return T.normalize(el.getAttribute('title'));
    }

    var content = T.normalize(contributedText(el));
    if (content) return content;

    return T.normalize(el.getAttribute('title'));
  }

  function hasAccessibleName(el) {
    return accessibleName(el) !== '';
  }

  global.A11yName = {
    accessibleName: accessibleName,
    hasAccessibleName: hasAccessibleName,
    contributedText: contributedText
  };
})(typeof window !== 'undefined' ? window : this);

/* ===== shared/a11y-injection-kit.js ===== */
/* ---------------------------------------------------------------------------
   a11y-injection-kit.js

   A guarded repair layer for closed platforms where the markup cannot be
   edited: Wix, Squarespace, and any embedded widget that renders its own DOM.

   Read shared/README.md before using this. Injection is a last resort. If the
   platform's own editor can set the thing you are about to patch, use the
   editor. A patch you own forever is worse than a setting the client owns.

   ---------------------------------------------------------------------------
   Design

   Closed platforms re-render. A page transition, a lightbox opening, a gallery
   advancing, a filter applying: all of them replace DOM that a one-shot
   DOMContentLoaded script has already processed. So the layer has to run
   again, which means it has to be safe to run again.

   Five properties make that safe. Each one is tested in test/kit.test.mjs
   rather than asserted here.

   1. Idempotent. Every element a rule touches gets a marker attribute and is
      skipped on later passes. Nothing is processed twice.

   2. Non-destructive. A rule that finds an element already carrying a correct
      name, label or role leaves it alone. The judgement of what counts as a
      name is made in one place, lib/accessible-name.js, not per rule.

   3. Observed, not polled. A MutationObserver costs nothing until the DOM
      changes. A setInterval costs battery on every page view forever. No rule
      in this repository is allowed to poll, and tools/verify.mjs fails the
      build if one does.

   4. Re-entrant safe, without going blind. The layer must not trigger itself,
      and it must not miss platform mutations that land while it is writing.
      Earlier versions of this file disconnected the observer for the duration
      of a pass, which solved the first problem by creating the second: any
      DOM the platform replaced during those few milliseconds was never seen
      again, because disconnect discards the queue. The observer now stays
      connected and the layer ignores records that describe only its own
      insertions, which carry a data-a11y-own marker. Anything else that
      arrives mid pass sets a flag and schedules one more pass.

   5. Failures are contained and visible. One rule throwing must not take the
      layer down, and a rule whose selector has stopped matching after a
      platform update must be discoverable. Both are what report() is for.

   ---------------------------------------------------------------------------
   Usage

     A11yKit.rule('name-cart-button', function (root, mark, kit) {
       root.querySelectorAll('[data-hook="cart"]').forEach(function (el) {
         if (mark(el)) return;
         el.setAttribute('aria-label', 'Cart');
       });
     });

     A11yKit.start();

   Debug in the browser console:

     A11yKit.report();     // what ran, how many elements each rule touched
     A11yKit.stop();       // disconnect, leaving the DOM as it is
   --------------------------------------------------------------------------- */

window.A11yKit = (function () {
  'use strict';

  /* Marker attributes get their own namespace rather than sharing the one
     rules select on. A rule called "announcement-close" used to mark its
     elements with data-a11y-announcement-close, which is exactly the kind of
     stable hook a rule wants to select by, so any element the page already
     carried that attribute on was treated as already handled and silently
     skipped. The rule looked registered, reported zero elements touched, and
     the finding it existed to fix stayed on the page. */
  var PREFIX = 'data-a11y-done-';
  var OWN = 'data-a11y-own';

  var rules = [];
  var names = {};
  var counters = {};
  var problems = [];

  var observer = null;
  var scheduled = false;
  var running = false;
  var dirtyWhileRunning = false;
  var passes = 0;

  /* Returns true if this element was already handled by this rule, and marks
     it if not. Rules call it first and return early when it returns true. */
  function makeMark(ruleName) {
    var attr = PREFIX + ruleName;
    return function mark(el) {
      if (!el || el.nodeType !== 1) return true;
      if (el.hasAttribute(attr)) return true;
      el.setAttribute(attr, '');
      counters[ruleName] = (counters[ruleName] || 0) + 1;
      return false;
    };
  }

  /* Every node the layer inserts is tagged, so the observer can tell its own
     work from the platform's. A rule that inserts a node without this still
     behaves correctly; it just costs one extra pass, and passes are cheap
     because every rule is idempotent. */
  function own(el) {
    if (el && el.nodeType === 1) el.setAttribute(OWN, '');
    return el;
  }

  function create(tagName) {
    return own(document.createElement(tagName));
  }

  function isOurs(node) {
    if (!node) return false;
    if (node.nodeType === 1) return node.hasAttribute(OWN);
    if (node.nodeType === 3) {
      return !!(node.parentNode && node.parentNode.nodeType === 1 &&
                node.parentNode.hasAttribute(OWN));
    }
    return false;
  }

  /* True when every added node in this batch is something the layer inserted
     and nothing was removed. Such a batch is our own echo and is ignored. */
  function isSelfInflicted(records) {
    for (var i = 0; i < records.length; i++) {
      var r = records[i];
      if (r.removedNodes && r.removedNodes.length) return false;
      for (var j = 0; j < r.addedNodes.length; j++) {
        if (!isOurs(r.addedNodes[j])) return false;
      }
    }
    return true;
  }

  function onMutations(records) {
    if (isSelfInflicted(records)) return;
    if (running) { dirtyWhileRunning = true; return; }
    schedule();
  }

  function runAll() {
    scheduled = false;
    if (running) { dirtyWhileRunning = true; return; }
    running = true;

    try {
      passes++;
      for (var i = 0; i < rules.length; i++) {
        try {
          rules[i].fn(document, makeMark(rules[i].name), api);
        } catch (err) {
          problems.push({ rule: rules[i].name, message: String(err && err.message || err) });
          if (window.console) {
            console.warn('[A11yKit] rule "' + rules[i].name + '" threw:', err);
          }
        }
      }
    } finally {
      running = false;
    }

    /* Anything the platform changed while the rules were writing has not
       been looked at yet. One more pass, coalesced like any other. */
    if (dirtyWhileRunning) {
      dirtyWhileRunning = false;
      schedule();
    }
  }

  function schedule() {
    if (scheduled) return;
    scheduled = true;
    /* Coalesce bursts of mutations into one pass per frame. Platform widgets
       emit mutations in the dozens; without this the layer runs dozens of
       times for one visible change. requestAnimationFrame does not fire in a
       background tab, which is correct here: a tab nobody is looking at does
       not need its focus order repaired this instant, and the queued pass
       runs as soon as the tab is shown. */
    var raf = window.requestAnimationFrame || function (fn) { return setTimeout(fn, 16); };
    raf(runAll);
  }

  function connect() {
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      /* Deliberately not observing attributes. Watching attribute changes on
         a platform that animates with inline styles produces a mutation storm
         and buys nothing, because the rules here key off structure. Rules that
         genuinely need to watch an attribute, such as the mobile navigation
         rule watching aria-expanded, open their own narrow observer. */
      attributes: false
    });
  }

  var api = {
    /* Register a repair. Rules run in registration order on every pass. */
    rule: function (name, fn) {
      if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(name)) {
        throw new Error('[A11yKit] rule name must be kebab-case: ' + name);
      }
      if (typeof fn !== 'function') {
        throw new Error('[A11yKit] rule "' + name + '" needs a function');
      }
      /* Two rules sharing a name share a marker attribute, so the second one
         silently skips every element the first one touched. That is a very
         quiet way to lose half a repair layer, so it is an error. */
      if (names[name]) {
        throw new Error('[A11yKit] duplicate rule name: ' + name);
      }
      names[name] = true;
      rules.push({ name: name, fn: fn });
      return this;
    },

    start: function () {
      if (observer) return this;
      var boot = function () {
        observer = new MutationObserver(onMutations);
        connect();
        runAll();
      };
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
      } else {
        boot();
      }
      return this;
    },

    stop: function () {
      if (observer) { observer.disconnect(); observer = null; }
      return this;
    },

    /* Run once immediately. Useful after a known platform navigation. A call
       that lands during a pass is queued rather than dropped. */
    refresh: function () {
      if (running) { dirtyWhileRunning = true; return this; }
      runAll();
      return this;
    },

    /* Mark a node as the layer's own, so inserting it does not look like a
       platform change. Rules should build elements with kit.create. */
    create: create,
    own: own,

    /* Console diagnostic. If a rule reports 0 after a platform update, its
       selector has probably stopped matching, which is the normal way these
       layers die silently. */
    report: function () {
      var out = { passes: passes, rules: {}, problems: problems.slice() };
      rules.forEach(function (r) { out.rules[r.name] = counters[r.name] || 0; });
      if (window.console && console.table) console.table(out.rules);
      return out;
    },

    /* Rule names in registration order. Used by the audit suite so the list
       of shipped rules cannot drift from the list of tested ones. */
    ruleNames: function () {
      return rules.map(function (r) { return r.name; });
    }
  };

  return api;
})();

/* ===== rules/01-skip-link.js ===== */
/* Rule: skip-link.  WCAG 2.4.1 Bypass Blocks.  Wix and Squarespace.

   Neither platform emits a skip link and neither has a setting for one, so
   this is one of the few repairs that genuinely belongs in injected code
   rather than in the editor.

   The defect this version fixes. The previous rule began with
   "if a skip link already exists, do nothing". On a platform that navigates
   without a reload, the body survives the transition and the skip link
   survives with it, while the main region it points at is replaced by a new
   element with a different id. The link then resolves to nothing: pressing
   Enter moves neither focus nor scroll, and because the link is still there
   and still looks right, nothing about the page suggests it has stopped
   working. The rule now re-points an existing link whose target has gone.

   The target needs tabindex="-1". Without it several browsers scroll to the
   anchor without moving focus, which is the same silent half-failure in a
   different costume. */

(function () {
  'use strict';
  if (!window.A11yKit) return;

  var MAIN = 'main, [role="main"], #PAGES_CONTAINER, #SITE_PAGES, #page, #content';
  var TARGET_ID = 'a11y-main';

  window.A11yKit.rule('skip-link', function (root, mark, kit) {
    var main = root.querySelector(MAIN);
    if (!main) return;

    if (!main.id) main.id = TARGET_ID;
    if (!main.hasAttribute('tabindex')) main.setAttribute('tabindex', '-1');

    var link = root.querySelector('.a11y-skip-link');

    if (link) {
      /* Re-point rather than return. This is the whole fix. */
      var href = link.getAttribute('href') || '';
      var current = href.charAt(0) === '#' ? root.getElementById(href.slice(1)) : null;
      if (current !== main) link.setAttribute('href', '#' + main.id);
      return;
    }

    link = kit.create('a');
    link.className = 'a11y-skip-link';
    link.setAttribute('href', '#' + main.id);
    link.textContent = 'Skip to main content';
    root.body.insertBefore(link, root.body.firstChild);
    mark(link);
  });
})();

/* ===== rules/02-name-controls.js ===== */
/* Rule: name-controls.  WCAG 4.1.2 Name, Role, Value.  Wix and Squarespace.

   Both platforms emit icon-only controls with no name: the header burger, the
   search toggle, gallery arrows, lightbox close buttons.

   The defect this version fixes. The previous rule decided a control was
   unnamed by reading textContent. A button whose only child is an image with
   correct alt text has an empty textContent and a perfectly good accessible
   name, so the rule appended a second name to it and the control announced
   its name twice. The same mistake treated an svg with a title element, and a
   control named through aria-labelledby pointing at a hidden span, as
   unnamed. All of that now goes through A11yName.accessibleName, which is one
   implementation tested against a case table in test/name.test.mjs.

   There is deliberately no fallback. A control this rule cannot identify is
   reported to the console for a human to name in the editor, and left alone.
   A guessed name is worse than a missing one, because a missing name is
   findable with a scanner and a wrong one is not. */

(function () {
  'use strict';
  if (!window.A11yKit || !window.A11yName || !window.A11yText) return;

  var CONTROLS = 'button, [role="button"], a[href], [role="link"], summary';

  window.A11yKit.rule('name-controls', function (root, mark, kit) {
    var all = root.querySelectorAll(CONTROLS);
    for (var i = 0; i < all.length; i++) {
      var el = all[i];
      if (window.A11yName.hasAccessibleName(el)) continue;
      if (mark(el)) continue;

      var probe = [
        el.getAttribute('data-testid'), el.getAttribute('data-hook'),
        el.getAttribute('data-test'), el.getAttribute('data-controls'),
        el.id, el.className
      ].join(' ');

      var name = window.A11yText.hintFor(probe);
      if (!name) {
        if (window.console) {
          console.info('[A11yKit] unnamed control, name it in the editor:', el);
        }
        continue;
      }

      var span = kit.create('span');
      span.className = 'a11y-visually-hidden';
      span.textContent = name;
      el.appendChild(span);
    }
  });
})();

/* ===== rules/03-filename-alt.js ===== */
/* Rule: filename-alt.  WCAG 1.1.1 Non-text Content.  Wix and Squarespace.

   Both editors prefill alt with the uploaded filename, so a site ends up
   announcing "D S C underscore zero zero four three dot J P G" where it
   should say nothing at all or say something useful.

   The defect this version fixes, and it is the worst one in the old set. The
   previous rule cleared the alt unconditionally, on the reasoning that a
   filename carries no information so the image may as well be decorative.
   That reasoning holds for an image sitting in a paragraph. It does not hold
   for an image that is the only content of a link or a button, where the alt
   is the control's entire accessible name. Clearing it there turns a badly
   named link into an unnamed one: a 1.1.1 problem the client could live with
   becomes a 2.4.4 and 4.1.2 problem that stops the control being usable at
   all. The repair made the site worse, and it did so silently.

   So the rule now asks what the image is for. Inside an interactive ancestor
   whose only name is this alt, it leaves the value alone and reports it. Any
   other image with a filename alt is marked decorative, which is the honest
   repair, and also reported, because the real fix is a human writing a real
   alt in the editor. */

(function () {
  'use strict';
  if (!window.A11yKit || !window.A11yName || !window.A11yText) return;

  var INTERACTIVE = 'a[href], button, [role="button"], [role="link"]';

  window.A11yKit.rule('filename-alt', function (root, mark, kit) {
    var images = root.querySelectorAll('img[alt]');
    for (var i = 0; i < images.length; i++) {
      var img = images[i];
      if (!window.A11yText.isFilenameAlt(img.getAttribute('alt'))) continue;
      if (mark(img)) continue;

      var host = img.closest ? img.closest(INTERACTIVE) : null;
      if (host) {
        /* Would clearing this alt leave the control with no name at all? */
        var before = img.getAttribute('alt');
        img.setAttribute('alt', '');
        var nameWithoutIt = window.A11yName.accessibleName(host);
        img.setAttribute('alt', before);

        if (!nameWithoutIt) {
          img.setAttribute('data-a11y-needs-alt', 'names-a-control');
          if (window.console) {
            console.warn('[A11yKit] this filename alt is the only name on a control, ' +
                         'so it has been left in place. Name the control in the editor:', host);
          }
          continue;
        }
      }

      img.setAttribute('alt', '');
      img.setAttribute('data-a11y-needs-alt', 'cleared');
      if (window.console) {
        console.info('[A11yKit] filename alt cleared, set a real alt in the editor:', img.currentSrc || img.src);
      }
    }
  });
})();

/* ===== rules/04-name-iframes.js ===== */
/* Rule: name-iframes.  WCAG 4.1.2 Name, Role, Value.  Wix and Squarespace.

   Embedded maps, booking widgets, video players and payment forms arrive as
   iframes with no title, and a screen reader announces an unnamed frame,
   which tells the user nothing about whether it is worth entering.

   The defect this version fixes. The previous selector was
   iframe:not([title]), which skips an iframe carrying title="". An empty
   title is exactly as useless as a missing one and is more common, because
   several embed builders emit the attribute and leave it blank. The rule now
   asks whether the frame has an accessible name, not whether it has an
   attribute. It also leaves a frame named by aria-label alone, which the old
   selector would have added a redundant title to.

   The limit is worth stating where the repair is. Naming the frame makes it
   findable. It does nothing whatsoever about what is inside it: a booking
   widget with an unlabelled date field is unreachable from the parent page,
   because no script on this origin can read or modify a cross-origin
   document. That one is an escalation to the vendor, not a repair. */

(function () {
  'use strict';
  if (!window.A11yKit || !window.A11yName) return;

  window.A11yKit.rule('name-iframes', function (root, mark, kit) {
    var frames = root.querySelectorAll('iframe');
    for (var i = 0; i < frames.length; i++) {
      var frame = frames[i];
      if (window.A11yName.hasAccessibleName(frame)) continue;
      if (mark(frame)) continue;

      var host = '';
      try { host = new URL(frame.getAttribute('src') || '', location.href).hostname; } catch (e) { host = ''; }
      frame.setAttribute('title', host ? ('Embedded content from ' + host) : 'Embedded content');
    }
  });
})();

/* ===== rules/05-mobile-nav-focus.js ===== */
/* Rule: mobile-nav-focus.  WCAG 2.1.2 No Keyboard Trap, 2.4.3 Focus Order.
   Squarespace, and Wix templates that use the same pattern.

   The most reliable finding on any site built on these platforms. The menu
   opens as a full screen overlay, focus is never moved into it, the page
   behind stays tabbable, and Escape does nothing. A keyboard user opens the
   menu and then tabs through the entire page underneath it, invisibly.

   No scanner reports this, and it is worth being precise about why: there is
   nothing in the DOM that distinguishes an overlay which manages focus from
   one which does not. The difference is in what happens on a key press, so
   the only way to find it is to press the key. That is what the audit in
   audit/checks.js does, and it is the reason this repository tests in a real
   browser rather than against parsed markup.

   The defect this version fixes, and it is the one that embarrassed the
   repository. The previous implementation watched the menu's open state with
   setInterval at 250ms, forever, on every page view. The kit's own
   documentation lists "observed, not polled" as one of its guarantees and
   gives "a setInterval burning battery on every page view forever" as the
   failure that guarantee exists to prevent. The flagship rule did the exact
   thing the flagship principle forbids. Worse, nothing cleared the interval,
   so a platform navigation that replaced the toggle element left the old
   timer running against a detached node and started a second one.

   It now watches the same signals with a narrow MutationObserver scoped to
   the two elements and the attributes that actually carry the state, and it
   disconnects when the toggle leaves the document. tools/verify.mjs fails
   the build if setInterval reappears anywhere in rules/. */

(function () {
  'use strict';
  if (!window.A11yKit) return;

  var FOCUSABLE = [
    'a[href]', 'button:not([disabled])',
    'input:not([disabled]):not([type="hidden"])',
    'select:not([disabled])', 'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])'
  ].join(', ');

  var TOGGLE = '.header-burger-btn, .Mobile-bar-menu, [data-test="header-burger"], .burger, [data-a11y-nav-toggle]';
  var OVERLAY = '.header-menu, .Mobile-overlay, .header-menu-nav, [data-a11y-nav-overlay]';

  window.A11yKit.rule('mobile-nav-focus', function (root, mark, kit) {
    var toggle = root.querySelector(TOGGLE);
    var overlay = root.querySelector(OVERLAY);
    if (!toggle || !overlay) return;
    if (mark(toggle)) return;

    var wasOpen = false;
    var watcher = null;

    function visible(el) {
      if (!el.getClientRects) return true;
      if (el.getClientRects().length) return true;
      /* getClientRects is empty in a headless layout for elements that are
         present and unstyled, so fall back to the attributes that actually
         say hidden. */
      return !el.hasAttribute('hidden') && el.getAttribute('aria-hidden') !== 'true';
    }

    function isOpen() {
      return root.body.classList.contains('header--menu-open') ||
             root.documentElement.classList.contains('Mobile-overlay--active') ||
             overlay.getAttribute('aria-hidden') === 'false' ||
             overlay.getAttribute('data-open') === 'true' ||
             toggle.getAttribute('aria-expanded') === 'true';
    }

    function items() {
      return Array.prototype.filter.call(overlay.querySelectorAll(FOCUSABLE), visible);
    }

    function onKeydown(e) {
      if (e.key === 'Escape') {
        e.preventDefault();
        toggle.click();
        toggle.focus();
        return;
      }
      if (e.key !== 'Tab') return;

      var list = items();
      if (!list.length) return;
      var first = list[0];
      var last = list[list.length - 1];
      var active = root.activeElement;

      /* Focus escaping the overlay is the defect, so both edges are wrapped,
         and so is the case where focus is somehow outside the overlay
         entirely, which happens when the platform moves it during the
         opening animation. */
      if (!overlay.contains(active)) { e.preventDefault(); first.focus(); return; }
      if (e.shiftKey && active === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && active === last) { e.preventDefault(); first.focus(); }
    }

    function sync() {
      if (!root.documentElement.contains(toggle)) {
        /* The platform replaced the header. Stop watching a detached node
           rather than leaking a watcher per navigation. */
        if (watcher) { watcher.disconnect(); watcher = null; }
        root.removeEventListener('keydown', onKeydown, true);
        return;
      }

      var open = isOpen();
      if (open === wasOpen) return;
      wasOpen = open;

      if (open) {
        var list = items();
        if (list.length) list[0].focus();
        root.addEventListener('keydown', onKeydown, true);
      } else {
        root.removeEventListener('keydown', onKeydown, true);
      }
    }

    /* Narrow and attribute scoped: the three nodes whose state matters, and
       only the attributes that carry it. This is the opposite of observing
       every attribute on the document, which is what the kit's global
       observer refuses to do for good reason. */
    watcher = new MutationObserver(sync);
    watcher.observe(toggle, { attributes: true, attributeFilter: ['aria-expanded', 'class'] });
    watcher.observe(overlay, { attributes: true, attributeFilter: ['aria-hidden', 'data-open', 'class'] });
    watcher.observe(root.body, { attributes: true, attributeFilter: ['class'] });
    watcher.observe(root.documentElement, { attributes: true, attributeFilter: ['class'] });

    sync();
  });
})();

/* ===== rules/06-summary-read-more.js ===== */
/* Rule: summary-read-more.  WCAG 2.4.4 Link Purpose (In Context).
   Squarespace summary blocks, and any blog or product grid built the same way.

   Every item in the list links with identical text. A screen reader user
   pulling up a list of links on the page gets twelve entries that all say
   "Read More" and no way to tell them apart.

   The visible wording is left alone on purpose. Changing it is a design
   decision that belongs to the client, and a repair layer that silently
   rewrites visible copy will eventually rewrite something it should not.
   Hidden text appended to the link makes each accessible name unique while
   the page looks exactly as the client built it.

   Two things this version does better. The generic phrase list is shared
   with the audit rather than written inline, so the rule and the check that
   grades it cannot disagree about what counts as generic. And the title it
   borrows is read with the shared accessible name computation, so an item
   whose title is an image with alt text gets a useful suffix instead of an
   empty one. */

(function () {
  'use strict';
  if (!window.A11yKit || !window.A11yName || !window.A11yText) return;

  var LINKS = '.summary-read-more-link, .summary-item a, [data-a11y-summary-item] a';
  var ITEM = '.summary-item, [data-a11y-summary-item], article, li';
  var TITLE = '.summary-title, .summary-title-link, h1, h2, h3, h4';

  window.A11yKit.rule('summary-read-more', function (root, mark, kit) {
    var links = root.querySelectorAll(LINKS);
    for (var i = 0; i < links.length; i++) {
      var link = links[i];
      if (!window.A11yText.isGenericLinkText(window.A11yName.accessibleName(link))) continue;
      if (mark(link)) continue;

      var item = link.closest ? link.closest(ITEM) : null;
      if (!item) continue;

      var titleEl = item.querySelector(TITLE);
      var title = titleEl ? window.A11yName.accessibleName(titleEl) : '';
      if (!title) continue;

      var span = kit.create('span');
      span.className = 'a11y-visually-hidden';
      span.textContent = ' about ' + title;
      link.appendChild(span);
    }
  });
})();

/* ===== rules/07-gallery-controls.js ===== */
/* Rule: gallery-controls.  WCAG 4.1.2 Name, Role, Value, and 2.1.1 Keyboard.
   Squarespace galleries and lightboxes, Wix Pro Gallery.

   Lightbox close, previous and next are commonly unnamed, and on several
   templates they are div or span elements rather than buttons.

   The defect this version fixes, and it is the subtle one. The previous rule
   named the control, and when the control was not a button it also added
   role="button" and tabindex="0" so it could be reached. What it never added
   was a key handler. The result is a control that a keyboard user can now
   tab to, that a screen reader now announces as a button named "Next image",
   and that does absolutely nothing when they press Enter or Space. Before the
   repair the control was unreachable, which is a failure the user can at
   least detect. After it, the control advertises an interaction it does not
   have, which wastes the user's time and makes them doubt their own input.
   Promising a role is a promise to implement it.

   So promotion is now atomic: role, tab stop and key handling go on together
   or none of them do. */

(function () {
  'use strict';
  if (!window.A11yKit || !window.A11yName) return;

  var MAP = [
    ['.gallery-lightbox-close, .lightbox-close, [data-controls="close"]', 'Close image viewer'],
    ['.gallery-arrow-left, .lightbox-control-previous, [data-controls="previous"]', 'Previous image'],
    ['.gallery-arrow-right, .lightbox-control-next, [data-controls="next"]', 'Next image']
  ];

  /* A native button already does this. Anything promoted to role="button"
     has to do it by hand, including the detail that Space fires on keyup and
     scrolls the page on keydown unless that is prevented. */
  function makeOperable(el) {
    el.addEventListener('keydown', function (e) {
      /* If the platform already handles this key it will have prevented the
         default, and activating again would fire the control twice. There is
         no way to ask an element whether it has a listener, so this is the
         only signal available and its limits are in
         docs/03-what-the-kit-cannot-reach.md. */
      if (e.defaultPrevented) return;
      if (e.key === ' ' || e.key === 'Spacebar') { e.preventDefault(); return; }
      if (e.key === 'Enter') { e.preventDefault(); el.click(); }
    });
    el.addEventListener('keyup', function (e) {
      if (e.defaultPrevented) return;
      if (e.key === ' ' || e.key === 'Spacebar') { e.preventDefault(); el.click(); }
    });
  }

  window.A11yKit.rule('gallery-controls', function (root, mark, kit) {
    for (var m = 0; m < MAP.length; m++) {
      var found = root.querySelectorAll(MAP[m][0]);
      for (var i = 0; i < found.length; i++) {
        var el = found[i];
        var needsName = !window.A11yName.hasAccessibleName(el);
        var isNative = el.tagName === 'BUTTON' || (el.tagName === 'A' && el.hasAttribute('href'));

        /* A native control that already has a name needs nothing. Anything
           else is managed, including an element that someone has already
           given a role and a tab stop and no key handling, because that
           state is invisible in the markup and is the worst of the three. */
        if (isNative && !needsName) continue;
        if (mark(el)) continue;

        if (needsName) el.setAttribute('aria-label', MAP[m][1]);

        if (!isNative) {
          if (!el.getAttribute('role')) el.setAttribute('role', 'button');
          if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');
          makeOperable(el);
        }
      }
    }
  });
})();

/* ===== rules/08-announcement-close.js ===== */
/* Rule: announcement-close.  WCAG 4.1.2 Name, Role, Value, and 2.1.1 Keyboard.
   Squarespace announcement bar.

   It deserves its own rule rather than a line in the gallery one, because of
   where it sits: first in the tab order, on every page of the site. An
   unnamed, unreachable close button in that position is the first thing a
   keyboard user meets and the thing they meet again on every navigation.

   Same promotion contract as the gallery rule. If this gives an element a
   button role and a tab stop, it also gives it key handling, because a
   control that announces itself as a button and ignores Enter is a worse
   outcome than one that was never reachable. */

(function () {
  'use strict';
  if (!window.A11yKit || !window.A11yName) return;

  var CLOSE = '.sqs-announcement-bar-close, [data-a11y-announcement-close]';

  function makeOperable(el) {
    el.addEventListener('keydown', function (e) {
      /* If the platform already handles this key it will have prevented the
         default, and activating again would fire the control twice. There is
         no way to ask an element whether it has a listener, so this is the
         only signal available and its limits are in
         docs/03-what-the-kit-cannot-reach.md. */
      if (e.defaultPrevented) return;
      if (e.key === ' ' || e.key === 'Spacebar') { e.preventDefault(); return; }
      if (e.key === 'Enter') { e.preventDefault(); el.click(); }
    });
    el.addEventListener('keyup', function (e) {
      if (e.defaultPrevented) return;
      if (e.key === ' ' || e.key === 'Spacebar') { e.preventDefault(); el.click(); }
    });
  }

  window.A11yKit.rule('announcement-close', function (root, mark, kit) {
    var found = root.querySelectorAll(CLOSE);
    for (var i = 0; i < found.length; i++) {
      var el = found[i];
      var needsName = !window.A11yName.hasAccessibleName(el);
      var isNative = el.tagName === 'BUTTON';

      /* Same contract as the gallery rule: a native button with a name is
         left alone, and anything else is managed as a whole. */
      if (isNative && !needsName) continue;
      if (mark(el)) continue;

      if (needsName) el.setAttribute('aria-label', 'Close announcement');
      if (!isNative) {
        if (!el.getAttribute('role')) el.setAttribute('role', 'button');
        if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');
        makeOperable(el);
      }
    }
  });
})();

/* ===== start ===== */
window.A11yKit.start();
